function ensureBrandPackage(){const board=brandBoard();board.master.logos=board.master.logos||[{id:'primary',name:'Primary logo',image:board.master.logo}];board.master.palette=board.master.palette||((board.master.colors||'').match(/#[0-9a-fA-F]{6}/g)||['#d0fc70','#151813']).slice(0,3);while(board.master.palette.length<2)board.master.palette.push('#151813');board.sets.forEach(set=>{if(!Array.isArray(set.visuals)){set.visuals=(board.refs||[]).filter(r=>r.setId===set.id);if(!set.visuals.length)set.visuals=[{key:'0-0',label:'Square',width:1080,height:1080,image:visualReference(0,0),photoSource:samplePhotos[0].source},{key:'3-1',label:'Story / vertical',width:1080,height:1920,image:visualReference(3,1),photoSource:samplePhotos[4%samplePhotos.length].source}];}});return board}
function validGuidelinePackage(set){return Boolean(set&&set.name?.trim()&&set.purpose?.trim()&&Array.isArray(set.visuals)&&set.visuals.length>0)}
const decorateBeforePackages=decorateBrand;decorateBrand=function(){decorateBeforePackages();if(currentPage!=='assets'||assetTab!=='brand')return;const library=document.querySelector('[data-brand-mode="visuals"]');if(library)library.remove();const sets=document.querySelector('[data-brand-mode="sets"]');if(sets)sets.textContent='Guideline sets · guide + visuals';ensureBrandPackage()};
const brandModeBeforePackages=renderBrandMode;renderBrandMode=function(mode){if(!can('assets.manage')){document.querySelector('#brand-editor-content').innerHTML='<p class="ops-muted">Manage asset groups permission is required to edit brand guidance.</p>';return}const board=ensureBrandPackage();if(mode==='visuals')mode='sets';brandModeBeforePackages(mode);if(mode==='master')enhanceMasterBrand(board);if(mode==='sets')enhanceGuidelinePackage(board);if(mode==='prompt'){const set=board.sets.find(s=>s.id===board.selected);const download=document.querySelector('#download-brand-brief');if(download&&(!validGuidelinePackage(set)||!set.reviewed)){download.disabled=true;download.title='A written guide, at least one visual reference, and human review are required.'}}};
function enhanceMasterBrand(board){const master=board.master,form=document.querySelector('#master-brand-form');const oldLogo=form.querySelector('.brand-logo-row');oldLogo.innerHTML=`<div style="width:100%"><h3>Logo versions</h3><p class="ops-muted">Store primary, reversed, monochrome and compact versions. Name each file so a future brief can choose the right variant.</p><div id="master-logo-versions" class="reference-samples" style="grid-template-columns:repeat(auto-fit,minmax(130px,1fr));margin:20px 0"></div><div class="field"><label for="master-logo-files">Add logo versions · PNG, JPEG, WebP · max 600 KB each</label><input id="master-logo-files" type="file" multiple accept="image/png,image/jpeg,image/webp"><small>Saved to this browser when you save the master direction. Existing uploads are kept.</small></div></div>`;let pendingLogos=master.logos.map(l=>({...l}));function logos(){document.querySelector('#master-logo-versions').innerHTML=pendingLogos.map((l,i)=>`<div class="card" style="padding:12px"><img style="height:85px;width:100%;object-fit:contain;background:#dce3d5;border-radius:5px" src="${l.image}" alt="${safe(l.name)}"><label class="field" style="margin-top:12px"><span>Version name</span><input data-logo-name="${i}" value="${safe(l.name)}" required></label><button class="btn" type="button" data-remove-logo="${i}" ${pendingLogos.length===1?'disabled':''}>Remove</button></div>`).join('');document.querySelectorAll('[data-logo-name]').forEach(input=>input.oninput=()=>pendingLogos[Number(input.dataset.logoName)].name=input.value);document.querySelectorAll('[data-remove-logo]').forEach(b=>b.onclick=()=>{pendingLogos.splice(Number(b.dataset.removeLogo),1);logos()})}logos();let readingLogos=false;document.querySelector('#master-logo-files').onchange=async e=>{const files=[...e.target.files];if(pendingLogos.length+files.length>8){toast('Use up to 8 logo versions in this browser demo.');return}readingLogos=true;const next=[];for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>600*1024){toast('Skipped '+file.name+': use PNG, JPEG or WebP under 600 KB.');continue}const image=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>resolve(null);reader.readAsDataURL(file)});if(image)next.push({id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),image})}pendingLogos.push(...next);readingLogos=false;logos()};const oldColor=document.querySelector('#master-colors').closest('.field');oldColor.innerHTML=`<label>Master colour palette · two or three colours</label><div id="master-palette" style="display:flex;flex-wrap:wrap;gap:16px">${[0,1,2].map(i=>`<div class="field"><label for="palette-${i}">${['Primary','Secondary','Accent (optional)'][i]}</label><input id="palette-${i}" placeholder="#AABBCC" pattern="#[0-9a-fA-F]{6}" ${i<2?'required':''} value="${safe(master.palette[i]||'')}" style="max-width:150px"></div>`).join('')}</div>`;form.onsubmit=e=>{e.preventDefault();if(readingLogos){toast('Wait for logo files to finish reading.');return}if(pendingLogos.some(l=>!l.name.trim())){toast('Name every logo version.');return}const palette=[0,1,2].map(i=>document.querySelector('#palette-'+i).value.trim()).filter(Boolean);if(palette.length<2||palette.length>3||palette.some(c=>!/^#[0-9a-fA-F]{6}$/.test(c))){toast('Enter two or three valid six-digit hex colours.');return}for(const key of ['name','font','voice','mood','tone','dos','donts'])master[key]=document.querySelector('#master-'+key).value.trim();master.palette=palette;master.colors=palette.join(' ');master.logos=pendingLogos;master.logo=pendingLogos[0]?.image||master.logo;board.sets.forEach(s=>s.reviewed=false);if(saveOps()){logOps('Master identity saved',pendingLogos.length+' logo versions; '+palette.length+' colours. All guideline sets require review.');toast('Master saved. Logos and palette inherited by every set.')}}}
function enhanceGuidelinePackage(board){const set=board.sets.find(s=>s.id===board.selected)||board.sets[0];const form=document.querySelector('#guideline-form');if(!form)return;const block=document.createElement('section');block.style.margin='25px 0';block.innerHTML='<h3>Visual references for this guideline</h3><p class="ops-muted">These visuals belong to this set. A written guide and at least one visual reference are required before review or AI-brief export.</p><div id="set-visuals" class="reference-grid"></div><button class="btn" type="button" id="add-set-reference" style="margin-top:16px">＋ Add visual reference</button>';form.querySelector('.preference-toggle').before(block);function drawVisuals(){document.querySelector('#set-visuals').innerHTML=set.visuals.map((r,i)=>`<article class="reference-format"><img src="${r.image}" alt="${safe(r.label)} reference for ${safe(set.name)}" referrerpolicy="no-referrer" style="width:100%;aspect-ratio:${r.width}/${r.height};max-height:210px;object-fit:cover;border-radius:5px"><h4>${safe(r.label)} <small>${r.width} × ${r.height}</small></h4>${r.photoSource?`<a class="asset-link" href="${r.photoSource}" target="_blank" rel="noopener noreferrer">Photo source / Unsplash</a>`:''}<button type="button" class="btn" data-remove-set-ref="${i}" style="margin-top:12px">Remove reference</button></article>`).join('')||'<p class="ops-muted">No visual references yet. Add one before marking this set reviewed.</p>';document.querySelectorAll('[data-remove-set-ref]').forEach(b=>b.onclick=()=>{set.visuals.splice(Number(b.dataset.removeSetRef),1);set.reviewed=false;saveOps();document.querySelector('#guideline-reviewed').checked=false;drawVisuals()})}drawVisuals();document.querySelector('#add-set-reference').onclick=()=>{for(const key of ['name','purpose','voice','dos','donts'])set[key]=document.querySelector('#set-'+key).value.trim();set.reviewed=false;saveOps();chooseSetReference(board,set)};form.onsubmit=e=>{e.preventDefault();for(const key of ['name','purpose','voice','dos','donts'])set[key]=document.querySelector('#set-'+key).value.trim();if(document.querySelector('#guideline-reviewed').checked&&!validGuidelinePackage(set)){toast('A guideline needs a name, written direction and at least one visual reference before review.');return}set.reviewed=document.querySelector('#guideline-reviewed').checked;logOps('Guideline package saved',set.name+'; '+set.visuals.length+' visual references; master rules retained.');toast('Guide and visual references saved together.')}}
function chooseSetReference(board,set){assetModal('Add visual reference to guideline',`<p class="form-description">Guideline: <strong>${safe(set.name)}</strong>. Choose a format and a photo; it will be attached only to this set.</p><div class="field"><label for="set-reference-size">Working canvas</label><select id="set-reference-size">${commonSizes.map(([l,w,h],i)=>`<option value="${i}">${l} · ${w} × ${h}</option>`).join('')}</select></div><div class="reference-samples" style="grid-template-columns:repeat(3,1fr)">${samplePhotos.map((p,i)=>`<button type="button" data-choose-set-photo="${i}"><img src="${samplePhoto(i,400)}" alt="${safe(p.alt)}" style="aspect-ratio:1;object-fit:cover"><small>${safe(p.author)} / Unsplash</small></button>`).join('')}</div><p class="ops-muted">Reference canvas sizes are not guarantees of platform specifications.</p>`);document.querySelectorAll('[data-choose-set-photo]').forEach(b=>b.onclick=()=>{const size=Number(document.querySelector('#set-reference-size').value),photo=Number(b.dataset.chooseSetPhoto),[label,width,height]=commonSizes[size];const key=size+'-'+photo;if(set.visuals.some(r=>r.key===key)){toast('This reference is already in the guideline.');return}set.visuals.push({key,label,width,height,image:samplePhoto(photo,Math.min(width,1200),Math.round(Math.min(width,1200)*height/width)),photoSource:samplePhotos[photo].source});set.reviewed=false;saveOps();close();renderBrandMode('sets');toast('Visual attached to this guideline. Review the updated package.')})}
const compileBeforePackages=compiledBrand;compiledBrand=function(board,set){const result=compileBeforePackages(board,set);return {...result,master:{...board.master,logos:board.master.logos,palette:board.master.palette},guideline:{...set},selectedVisualReferences:set.visuals||[],packageValid:validGuidelinePackage(set)}};
